import{_ as i,l as d,o as l,c as p,v as a,p as r,x as o,d as s,i as c,S as n}from"./chunks/framework.InCnrqk-.js";const A=JSON.parse('{"title":"epoll","description":"","frontmatter":{"title":"epoll","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/epoll.md","filePath":"cs/epoll.md","lastUpdated":1789023840000}'),_={name:"cs/epoll.md"};function h(E,e,f,m,u,B){const t=d("Mermaid");return l(),p("div",null,[e[1]||(e[1]=a('<h1 id="epoll" tabindex="-1">epoll <a class="header-anchor" href="#epoll" aria-label="Permalink to &quot;epoll&quot;">​</a></h1><div class="epigraph"><p>在内核为进程保存兴趣表；就绪事件放进队列，wait 不必每次携带并扫描全部描述符。</p><footer>—— 据 Linux epoll 手册；Stevens 对大规模事件通知的讨论</footer></div><p><a href="/cs/select-poll">上一课</a>每次把 n 个 fd 拷进内核做 O(n) 扫描。连接数上万时，扫描本身比工作还重。缺口是 <strong>epoll</strong>：<code>epoll_ctl</code> 改兴趣，<code>epoll_wait</code> 只取已就绪。合并水平与边沿触发，不当两篇词条。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>select 的兴趣是调用参数，无状态。epoll 实例是一个 fd，内核红黑树（或等价）记住监视哪些 fd、要哪些事件。文件真正就绪时，回调把该项放进就绪链表。wait 只收割链表。缺口不是新的管道，而是这份内核状态以及 ET（边沿：只在状态变化时报告）与 LT（水平：与 poll 相同）的差别。</p><p>本课不把 <code>epoll_ctl</code> 每个 op 的错误码背完。</p><p><span class="marginnote">ET 要求一次读到 EAGAIN，否则事件丢失在应用逻辑里。LT 更不易用错，就绪队列可能反复报告同一 fd。本课不写攻击，只写语义。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><code>epoll_create</code> → 对每个连接 <code>EPOLL_CTL_ADD</code> → 循环 <code>epoll_wait</code> → 对返回的 fd 做非阻塞 <code>read</code>/<code>write</code>。关闭 fd 会自动从兴趣表删除（实现相关，教学上仍应显式 DEL）。与 <a href="/cs/sigmask">信号掩码</a> 可用 <code>epoll_pwait</code> 原子搭配。底层仍是各文件的 poll 回调，与 VFS 操作表相连。</p>',9)),(l(),r(n,null,{default:o(()=>[c(t,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20CTL%5B%22epoll_ctl%20%E5%85%B4%E8%B6%A3%E8%A1%A8%22%5D%20--%3E%20CB%5B%22%E6%96%87%E4%BB%B6%E5%B0%B1%E7%BB%AA%E5%9B%9E%E8%B0%83%22%5D%0A%20%20CB%20--%3E%20RQ%5B%22%E5%B0%B1%E7%BB%AA%E9%98%9F%E5%88%97%22%5D%0A%20%20RQ%20--%3E%20WAIT%5B%22epoll_wait%20%E6%94%B6%E5%89%B2%22%5D%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[s(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>epoll 把复杂度从「每次系统调用 × n」降到「事件发生时 O(1) 插入 + wait 收割」。它仍是同步 I/O 的就绪通知，不是下一课的异步提交。线程安全：同一 epoll fd 可被多线程 wait，语义要小心惊群——实现有过变化，主干只承认「有这个对象」。</p><p>不要把 epoll 写成 Windows IOCP 的逐条对照表。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 <code>io_uring</code> 的 SQE。不保证 epoll 在所有文件类型上等价（部分设备 poll 实现粗糙）。下一课：把「等就绪再 read」换成「提交读请求，完成进队列」，进一步减少陷入。</p><p>后课默认：兴趣表可规模化。系统调用本身仍是每批 wait；下一课 io_uring 用共享环形缓冲提交与完成。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>epoll 在内核保存兴趣并维护就绪队列。</li><li>LT 似 poll；ET 只报变化，要读到 EAGAIN。</li><li>异步提交完成队列是 io_uring 的缺口。</li><li>出处：Linux <code>epoll(7)</code>；Stevens；Love, <em>LKD</em>。</li></ul>',8))])}const x=i(_,[["render",h]]);export{A as __pageData,x as default};
